do $$ declare r record; v_name text; begin for r in select n.nspname as schema_name,c.relname as table_name,a.attname as column_name,con.conname from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace join lateral unnest(con.conkey) with ordinality as k(attnum,ord) on true join pg_attribute a on a.attrelid=c.oid and a.attnum=k.attnum where con.contype='f' and n.nspname='public' and k.ord=1 and not exists (select 1 from pg_index i where i.indrelid=c.oid and i.indisvalid and i.indisready and i.indnkeyatts>=1 and i.indkey[0]=a.attnum) loop v_name:=left('idx_fk_'||r.table_name||'_'||r.column_name,55)||'_'||substr(md5(r.conname),1,8); execute format('create index if not exists %I on %I.%I (%I)',v_name,r.schema_name,r.table_name,r.column_name); end loop; end $$;
